def get_tags_by_axis(axis: str) -> list[Tag]:
    return [t for t in TAGS if t.axis == axis]


def get_all_tag_ids() -> list[str]:
    return [t.id for t in TAGS]


if __name__ == "__main__":
    print(f"axes: {AXES}")
    print(f"total tags: {len(TAGS)}")
    print(f"char refs: {len(CHAR_REFS)}")
    for ax in AXES:
        n = len(get_tags_by_axis(ax))
        print(f"  {ax:<22} {n}")
